{"content": "/*
 * AutoRCCar - RC car motor control (Arduino)
 *
 * Reads single-character commands from the serial port (115200 baud) sent
 * by the computer (computer/rc_driver.py, RCControl class) or by the data
 * collection tool, and drives the two DC motors through an L298N-style
 * H-bridge driver. This sketch is what makes the "RC keyboard control"
 * possible: the PC forwards arrow-key presses as serial commands.
 *
 * Wiring (L298N motor driver module):
 *   IN1  -> digital 8   (left motor direction pin 1)
 *   IN2  -> digital 7   (left motor direction pin 2)
 *   IN3  -> digital 5   (right motor direction pin 1)
 *   IN4  -> digital 4   (right motor direction pin 2)
 *   ENA  -> digital 9   (left motor PWM / enable)
 *   ENB  -> digital 6   (right motor PWM / enable)
 *
 * Serial command table (ASCII characters):
 *   '0'  stop
 *   '1'  forward
 *   '2'  left turn
 *   '3'  right turn
 *   '4'  stop
 *   '5'  forward + left   (compound)
 *   '6'  forward + right  (compound)
 *   '7'  backward
 *   '8'  backward + left  (compound)
 *   '9'  backward + right (compound)
 */

const int leftDir1 = 8;
const int leftDir2 = 7;
const int rightDir1 = 5;
const int rightDir2 = 4;
const int leftEnable = 9;
const int rightEnable = 6;

const int SPEED = 180;  // PWM speed 0..255 (tune for your motors)

void setup() {
  pinMode(leftDir1, OUTPUT);
  pinMode(leftDir2, OUTPUT);
  pinMode(rightDir1, OUTPUT);
  pinMode(rightDir2, OUTPUT);
  pinMode(leftEnable, OUTPUT);
  pinMode(rightEnable, OUTPUT);

  Serial.begin(115200);
  stopCar();
}

void leftMotorForward(int speed) {
  digitalWrite(leftDir1, LOW);
  digitalWrite(leftDir2, HIGH);
  analogWrite(leftEnable, speed);
}

void leftMotorBackward(int speed) {
  digitalWrite(leftDir1, HIGH);
  digitalWrite(leftDir2, LOW);
  analogWrite(leftEnable, speed);
}

void rightMotorForward(int speed) {
  digitalWrite(rightDir1, LOW);
  digitalWrite(rightDir2, HIGH);
  analogWrite(rightEnable, speed);
}

void rightMotorBackward(int speed) {
  digitalWrite(rightDir1, HIGH);
  digitalWrite(rightDir2, LOW);
  analogWrite(rightEnable, speed);
}

void leftMotorStop() {
  analogWrite(leftEnable, 0);
  digitalWrite(leftDir1, LOW);
  digitalWrite(leftDir2, LOW);
}

void rightMotorStop() {
  analogWrite(rightEnable, 0);
  digitalWrite(rightDir1, LOW);
  digitalWrite(rightDir2, LOW);
}

void forward() {
  leftMotorForward(SPEED);
  rightMotorForward(SPEED);
}

void backward() {
  leftMotorBackward(SPEED);
  rightMotorBackward(SPEED);
}

void leftTurn() {
  leftMotorStop();
  rightMotorForward(SPEED);
}

void rightTurn() {
  leftMotorForward(SPEED);
  rightMotorStop();
}

void forwardLeft() {
  leftMotorBackward(SPEED / 2);
  rightMotorForward(SPEED);
}

void forwardRight() {
  leftMotorForward(SPEED);
  rightMotorBackward(SPEED / 2);
}

void backwardLeft() {
  leftMotorForward(SPEED / 2);
  rightMotorBackward(SPEED);
}

void backwardRight() {
  leftMotorBackward(SPEED);
  rightMotorForward(SPEED / 2);
}

void stopCar() {
  leftMotorStop();
  rightMotorStop();
}

void loop() {
  if (Serial.available() > 0) {
    char in = Serial.read();
    switch (in) {
      case '0':
        stopCar();
        break;
      case '1':
        forward();
        break;
      case '2':
        leftTurn();
        break;
      case '3':
        rightTurn();
        break;
      case '4':
        stopCar();
        break;
      case '5':
        forwardLeft();
        break;
      case '6':
        forwardRight();
        break;
      case '7':
        backward();
        break;
      case '8':
        backwardLeft();
        break;
      case '9':
        backwardRight();
        break;
    }
  }
  delay(10);
}
