{"content": "/*
 * AutoRCCar - Traffic signal controller (Arduino)
 *
 * Drives the red / yellow / green LEDs of the toy traffic light that the
 * RC car must obey. Default sequence (repeating):
 *
 *     red 5 s -> green 5 s -> yellow 2 s
 *
 * Wiring:
 *     Red LED    anode -> 330 ohm -> digital 3, cathode -> GND
 *     Yellow LED anode -> 330 ohm -> digital 4, cathode -> GND
 *     Green LED  anode -> 330 ohm -> digital 5, cathode -> GND
 *
 * Optional serial control (115200 baud):
 *     'R' force red
 *     'Y' force yellow
 *     'G' force green
 *     'C' resume the automatic cycle
 */

const int redLed = 3;
const int yellowLed = 4;
const int greenLed = 5;

const unsigned long redTime = 5000;    // ms
const unsigned long greenTime = 5000;  // ms
const unsigned long yellowTime = 2000; // ms

enum State { RED, GREEN, YELLOW, MANUAL };

State state = RED;
State manualState = RED;
unsigned long stateStart = 0;

void setLights() {
  digitalWrite(redLed, state == RED ? HIGH : LOW);
  digitalWrite(yellowLed, state == YELLOW ? HIGH : LOW);
  digitalWrite(greenLed, state == GREEN ? HIGH : LOW);
}

void setup() {
  pinMode(redLed, OUTPUT);
  pinMode(yellowLed, OUTPUT);
  pinMode(greenLed, OUTPUT);
  Serial.begin(115200);
  stateStart = millis();
  setLights();
}

void loop() {
  if (Serial.available() > 0) {
    char in = toupper(Serial.read());
    if (in == 'R') {
      manualState = RED;
      state = MANUAL;
    } else if (in == 'Y') {
      manualState = YELLOW;
      state = MANUAL;
    } else if (in == 'G') {
      manualState = GREEN;
      state = MANUAL;
    } else if (in == 'C') {
      state = RED;
      stateStart = millis();
    }
    if (state == MANUAL) {
      setLights();
      return;
    }
  }

  if (state != MANUAL) {
    unsigned long now = millis();
    unsigned long elapsed = now - stateStart;
    switch (state) {
      case RED:
        if (elapsed >= redTime) {
          state = GREEN;
          stateStart = now;
        }
        break;
      case GREEN:
        if (elapsed >= greenTime) {
          state = YELLOW;
          stateStart = now;
        }
        break;
      case YELLOW:
        if (elapsed >= yellowTime) {
          state = RED;
          stateStart = now;
        }
        break;
      default:
        break;
    }
    setLights();
  }
  delay(50);
}
